from pathlib import Path
from html import escape
import re
ROOT=Path(__file__).resolve().parents[1]; DIST=ROOT/'dist'
home=(DIST/'index.html').read_text()
def bi(tag,zh,en,attrs=''):
 return f'<{tag} data-en="{escape(en,quote=True)}" {attrs}>{zh}</{tag}>'
def img(src,zh,en,cls='',eager=False):
 from PIL import Image
 w,h=Image.open(DIST/'assets'/src).size
 return f'<img src="/assets/{src}" width="{w}" height="{h}" alt="{zh}" data-alt-en="{escape(en,quote=True)}" class="{cls}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def button(zh,en,href,light=False):
 return f'<a class="button {"button-light" if light else "button-dark"}" href="{href}">{bi("span",zh,en)}<span aria-hidden="true">↗</span></a>'
def label(zh,en):return bi('p',zh,en,'class="eyebrow"')
def title(zh,en):return bi('h2',zh,en)
def intro(eyebrow,zh,en,bodyzh='',bodyen=''):
 return f'<div class="section-heading reveal">{label(eyebrow,eyebrow)}{title(zh,en)}'+(bi('p',bodyzh,bodyen,'class="section-lead"') if bodyzh else '')+'</div>'
header=re.search(r'<header.*?</header>\s*<nav id="mobile-nav".*?</nav>',home,re.S).group()
footer=re.search(r'<footer.*?</footer>',home,re.S).group().replace('href="#home" class="back-top"','href="#main" class="back-top"')
cta=re.search(r'<section class="home-cta.*?</section>',home,re.S).group()
wellness=re.search(r'<section class="wellness.*?</section>',home,re.S).group()
favicon=re.search(r'<link rel="icon"[^>]+>',home).group()
def root_paths(s):return s.replace('src="assets/','src="/assets/').replace('href="#home"','href="/#home"')
def wrap(route,page,zh,en,body,heroasset='',solid=False):
 nav=header.replace(' aria-current="page"','')
 nav=nav.replace(f'href="/{route}/"',f'href="/{route}/" aria-current="page"')
 nav=re.sub(r' data-page="[^"]+"','',nav)
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f2eb"><meta name="description" content="{zh} — RHYVIA 水平律动座椅，让舒适融入日常。"><title>{zh} — RHYVIA</title>{favicon}<link rel="stylesheet" href="/style.css?v=compat-4"><link rel="stylesheet" href="/pages.css?v=gallery-20261019-2">{'<link rel="stylesheet" href="/expertise.css?v=20261019-5">' if page == "story" else ""}{f'<link rel="preload" as="image" href="/assets/{heroasset}">' if heroasset else ''}</head><body class="inner-page page-{page} {'solid-header' if solid else ''}" data-title-zh="{zh} — RHYVIA" data-title-en="{en} — RHYVIA"><a class="skip-link" href="#main" data-i18n="skip">跳至内容</a>{root_paths(nav)}<main id="main">{body}</main>{root_paths(footer)}<script src="/language.js?v=1" defer></script><script src="/site-config.js?v=1" defer></script><script src="/site.js?v=language-3" defer></script><script src="/ripple.js?v=7" defer></script><script src="/cursor.js?v=3" defer></script>{'<script src="/expertise-globe.js?v=3" defer></script>' if page == "story" else ""}</body></html>'''
 out=DIST/route;out.mkdir(exist_ok=True);(out/'index.html').write_text(html)
def hero(klass,asset,eyebrow,zh,en,bodyzh,bodyen,href,ctazh,ctaen):
 return f'<section class="inner-hero {klass}" id="top"><div class="inner-hero-media">{img(asset,zh.replace("<br>",""),en.replace("<br>"," "),eager=True)}</div><div class="inner-hero-shade"></div><div class="inner-hero-copy reveal">{label(eyebrow,eyebrow)}{bi("h1",zh,en)}{bi("p",bodyzh,bodyen,"class=hero-lead")}{button(ctazh,ctaen,href)}</div><div class="inner-hero-bottom">{bi("span","律动 · 舒适 · 日常","RHYTHM · COMFORT · EVERY DAY")}<a href="{href}" aria-label="Scroll down">↓</a></div></section>'
products=[
 dict(id='one',name='ONE',n='01',tag=('小巧精致，自在安坐。','A little space.<br>A world of comfort.'),brief=('日常安坐 · 独立脚踏','Everyday seating · Separate footrest'),body=('以舒适的直立坐姿，陪伴阅读、休息与日常放松。独立脚踏让双腿自然舒展，小巧的体量，让舒适轻松融入客厅、卧室或属于自己的安静角落。','An upright seat for reading, pausing and everyday relaxation. A separate footrest lets your legs settle comfortably, while the compact form finds its place in a living room, bedroom or quiet corner.'),features=[('舒适直立坐姿','Comfortable upright seating'),('独立配套脚踏','A separate, matching footrest'),('平稳水平律动','Smooth horizontal motion'),('紧凑的居家设计','A compact form for everyday spaces')],scene='chair-one-scene-20261019.jpg',images=[('chair-one-angle-20261019.jpg', '整体外观', 'Overview'), ('chair-one-front-20261019.jpg', '正面', 'Front'), ('chair-one-backrest-20261019.jpg', '靠背细节', 'Backrest'), ('chair-one-controls-20261019.jpg', '控制面板', 'Controls'), ('chair-one-trim-20261019.jpg', '饰面细节', 'Trim detail')]),
 dict(id='two',name='TWO',n='02',tag=('深度后仰，轻松卸下一天。','Lean back.<br>Let the day settle.'),brief=('后仰承托 · 包裹式舒适','Reclined support · Cocooning comfort'),body=('让身体慢慢向后，找到被温柔承托的姿态。柔软的包裹感与轻柔律动相伴，为傍晚的休憩、安静的独处，留出一段不被打扰的时间。','Settle back into a deeply supported position. Soft cushioning and gentle motion create a cocooning place for evening pauses, quiet moments and a little uninterrupted time to yourself.'),features=[('舒适后仰姿态','A comfortably reclined position'),('从头到脚的承托','Support from head to toe'),('柔软包裹的座椅设计','Soft, enveloping cushioning'),('适合晚间放松','Made for unwinding in the evening')],scene='chair-two-scene-20261019.jpg',images=[('chair-two-angle-20261019.jpg', '整体外观', 'Overview'), ('chair-two-front-20261019.jpg', '正面', 'Front'), ('chair-two-side-20261019.jpg', '侧面', 'Side'), ('chair-two-backrest-20261019.jpg', '头枕与靠背', 'Headrest'), ('chair-two-armrest-20261019.jpg', '扶手细节', 'Armrest')]),
 dict(id='three',name='THREE',n='03',tag=('舒展全身，让从容停留。','Stretch out.<br>Stay a little longer.'),brief=('加长躺椅 · 全身舒展','Extended lounger · Room to unwind'),body=('宽敞的躺椅式设计，为身体留出更多舒展空间。流畅轮廓、一体式扶手与柔软面料相互呼应，让片刻休憩成为家中自然的一部分。','An extended lounge form gives your body more room to settle. Flowing lines, integrated armrests and soft upholstery come together in a considered piece for unhurried rest at home.'),features=[('加长型全身承托','Extended full-body support'),('宽敞躺椅式设计','A spacious lounge silhouette'),('一体式扶手','Integrated armrests'),('便于操作的侧边控制','Convenient side controls')],scene='chair-three-scene.png',images=[('chair-three-front-transparent.png', '正面', 'Front'), ('chair-three-side-transparent.png', '侧面', 'Side'), ('chair-three-back-transparent.png', '背面', 'Back')])]
body='<section class="collection-intro section-pad">'+label('OUR CHAIRS · 座椅系列','OUR CHAIRS')+'<div class="intro-columns reveal">'+bi('h1','三款座椅。<br>舒适，各有其形。','Three chairs.<br>Your kind of comfort.')+'<div>'+bi('p','将轻柔的水平律动，融入设计精美的座椅之中。<br><br>从自在安坐，到舒展全身。选择适合你的空间、姿态与日常节奏的一款。','Gentle horizontal motion, thoughtfully built into furniture.<br><br>From upright ease to full-body rest, find the chair that suits your space, your posture and your everyday rhythm.','class="section-lead"')+'<a href="#compare" class="text-link">'+bi('span','比较三款座椅','Compare the collection')+' ↗</a></div></div></section><section class="collection-overview" aria-label="RHYVIA chairs">'
for p in products:
 body+=f'<a class="collection-card reveal" href="#{p["id"]}"><div class="collection-image">{img(p["scene"],"RHYVIA "+p["name"]+" 场景图","RHYVIA "+p["name"]+" in its setting")}</div><div class="collection-caption"><div><span class="eyebrow">RHYVIA {p["name"]}</span>{bi("p",*p["brief"])}</div><span aria-hidden="true">↗</span></div></a>'
body+='</section><div class="product-list">'
for p in products:
 gallery=f'<div class="product-gallery reveal {'gallery-updated' if p["id"] in ("one","two") else ''}" data-gallery><div class="gallery-main">{img(p["images"][0][0],"RHYVIA "+p["name"]+" "+p["images"][0][1],"RHYVIA "+p["name"]+" "+p["images"][0][2], "gallery-photo")}<span class="gallery-count">01 / {len(p["images"]):02d}</span></div><div class="gallery-thumbs" role="group" aria-label="Product images">'
 for i,(src,z,e) in enumerate(p['images']):
  gallery+=f'<button type="button" class="gallery-thumb" aria-pressed="{str(i==0).lower()}" data-image="/assets/{src}" data-image-alt-zh="RHYVIA {p["name"]} {z}" data-image-alt-en="RHYVIA {p["name"]} {e}">{img(src,"","")}{bi("span",z,e)}</button>'
 gallery+='</div></div>'
 body+=f'<section class="product-section section-pad" id="{p["id"]}">{gallery}<div class="product-copy reveal"><p class="eyebrow"><span>{p["n"]}</span> RHYVIA {p["name"]}</p>{title(*p["tag"])}{bi("p",*p["body"],"class=section-lead")}<ul class="feature-list">'+''.join(bi('li',z,e) for z,e in p['features'])+'</ul>'+bi('p','尺寸、面料与配置，请在预约时向体验顾问确认。','Please confirm dimensions, upholstery and available options with your experience advisor.','class="spec-note"')+button('预约体验 '+p['name'],'Experience '+p['name'],f'/experience/?chair={p["name"]}#booking')+'</div></section>'
body+='</div><section id="compare" class="comparison section-pad">'+intro('FIND YOUR FIT','哪一款，更适合你的日常？','Which one feels like you?')+'<div class="table-scroll reveal"><table><caption class="sr-only">'+bi('span','三款座椅特点比较','Compare the three chairs')+'</caption><thead><tr>'+bi('th','你的偏好','Your preference')+''.join(f'<th scope="col">RHYVIA {p["name"]}</th>' for p in products)+'</tr></thead><tbody>'
for labelpair,vals in [(('舒适姿态','How you settle'),[('直立安坐','Upright seating'),('深度后仰','Reclined support'),('舒展躺卧','Extended lounging')]),(('腿部承托','Leg support'),[('独立脚踏','Separate footrest'),('一体式腿部承托','Integrated leg support'),('加长躺椅式承托','Extended lounge support')]),(('日常场景','Your everyday moment'),[('阅读与片刻放松','Reading and everyday pauses'),('晚间休憩','Unwinding in the evening'),('从容舒展与休息','Longer, unhurried rest')]),(('共同体验','What they share'),[('轻柔水平律动','Gentle horizontal motion')]*3)]:
 body+='<tr>'+bi('th',*labelpair,'scope="row"')+''.join(bi('td',*v) for v in vals)+'</tr>'
body+='</tbody></table></div></section>'+root_paths(cta)
wrap('chairs','chairs','座椅系列','Our chairs',body,solid=True)

# Technology: keep the draft narrative without publishing unverified medical claims.
body=hero('technology-hero','technology-hero.png','OUR TECHNOLOGY','轻柔律动，<br>舒适日常。','Gentle rhythm.<br>Every day.','让运动结构、节奏控制与座椅设计协同工作，<br>把从容的放松体验带进日常。','Motion, rhythm and thoughtful seating, working together.<br>Made for a little more ease in your everyday life.','#motion','了解水平律动','Discover horizontal motion')+root_paths(wellness)
